INSERT INTO standard_process_clause_map (standard_code, process_group_id, actual_clause_no, clause_topic, guide_note) VALUES ('ISO9001', 'PG6', '8.3', '설계·개발', '입력·출력, 검토·검증·유효성확인이 되어있는지 확인하세요.');
