INSERT INTO standard_process_clause_map (standard_code, process_group_id, actual_clause_no, clause_topic, guide_note) VALUES ('ISO14001', 'PG6', '8.1/8.2', '운용관리(수명주기 관점) 및 비상사태 대비·대응', '설계·조달·폐기까지 전체 수명주기 관점과 비상사태 대비·대응을 확인하세요. (14001은 8.2가 따로 없고 8.1에 포함됩니다)');
