INSERT INTO standard_clause_map (standard_code, hls_code, actual_clause_no, status, integrated_into_hls_code, guide_note) VALUES ('ISO37001', '10.2', '8.8~8.10', 'ADDITIONAL', NULL, '부패가 발생하거나 의심될 때 조사·제재·통제개선이 이뤄지는지 확인하세요.');
INSERT INTO standard_clause_map (standard_code, hls_code, actual_clause_no, status, integrated_into_hls_code, guide_note) VALUES ('ISO19443', '10.2', '10.2', 'ADDITIONAL', NULL, '부적합품을 고객에게 알리고, 위조품(CFSI) 발견 시 조치하는지 확인하세요.');
INSERT INTO standard_clause_map (standard_code, hls_code, actual_clause_no, status, integrated_into_hls_code, guide_note) VALUES ('ISO27001', '10.2', '10.2', 'RENUMBERED', NULL, '27001은 10.2가 \\'부적합 및 시정조치\\'입니다. 내용은 9001과 같고 번호 순서만 반대입니다.');
INSERT INTO standard_clause_map (standard_code, hls_code, actual_clause_no, status, integrated_into_hls_code, guide_note) VALUES ('ISO50001', '10.3', '10.3', 'ADDITIONAL', NULL, '에너지성과가 실제로 계속 좋아지고 있는지(EnPI 추이) 확인하세요. 이 표준의 핵심 요구사항입니다.');
INSERT INTO standard_clause_map (standard_code, hls_code, actual_clause_no, status, integrated_into_hls_code, guide_note) VALUES ('ISO45001', '10.3', '10.3', 'ADDITIONAL', NULL, '개선 결과를 근로자와 소통하고 참여시키는지 확인하세요.');
INSERT INTO standard_clause_map (standard_code, hls_code, actual_clause_no, status, integrated_into_hls_code, guide_note) VALUES ('ISO14001', '10.3', '10.3', 'ADDITIONAL', NULL, '환경성과가 실제로 개선되고 있는지 확인하세요.');
